      ctx.fillStyle = 'rgba(255,210,63,0.25)'; ctx.beginPath(); ctx.arc(rp.x, rp.y, 46, 0, 7); ctx.fill();
    }
    const marker = missionTarget(game);
    if (marker) {
      const pulse = 26 + Math.sin(time * 4) * 6;
      ctx.strokeStyle = PALETTE.marker; ctx.lineWidth = 4;
