      ctx.fillStyle = '#5a1f1f'; ctx.beginPath(); ctx.arc(0, 0, 11, 0, 7); ctx.fill();
      ctx.fillStyle = '#e8b98a'; ctx.beginPath(); ctx.arc(5, 0, 5, 0, 7); ctx.fill();
