      ctx.fillStyle = '#2b6cb0'; ctx.beginPath(); ctx.arc(0, 0, 11, 0, 7); ctx.fill();
      ctx.fillStyle = '#f2c9a0'; ctx.beginPath(); ctx.arc(6, 0, 5, 0, 7); ctx.fill();
