  function drawMinimap(city, game) {
    const s = game.state;
    const size = 168, x0 = viewW - size - 14, y0 = 14;
    const k = size / WORLD.size;
    ctx.fillStyle = PALETTE.hudPanel; ctx.fillRect(x0 - 4, y0 - 4, size + 8, size + 8);
